{"content":""""Scratch probe: reproduce the DAG-list order_by AttributeError.

Mimics airflow's SortParam resolution (airflow-core/src/airflow/api_fastapi/
common/parameters/sort.py::_resolve) against stub models, using the ACTUAL
allowed_attrs / to_replace keys parsed from the repo's route files via AST
(so this exercises the deliverable without needing airflow installed).

Stub DagModel exposes exactly the attributes the real DagModel has among the
sort keys (dag_id, dag_display_name, next_dagrun) and lacks state/start_date,
matching the real model.
"""

import ast
import sys

REPO_FILES = {
    "public": "routes/public/dags.py",
    "ui": "routes/ui/dags.py",
}


class FakeColumn:
    def __init__(self, name):
        self.key = name


class FakeModel:
    def __init__(self, name, attrs):
        self._name = name
        for a in attrs:
            setattr(self, a, FakeColumn(a))

    def __repr__(self):
        return f"<{self._name}>"


DagModel = FakeModel("DagModel", ["dag_id", "dag_display_name", "next_dagrun"])
DagRun = FakeModel("DagRun", ["state", "start_date", "run_after"])


class HTTP400(Exception):
    pass


def parse_sort_param(path):
    """Extract (allowed_attrs, to_replace_keys) from the SortParam(...) call."""
    tree = ast.parse(open(path).read())
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and getattr(node.func, "id", "") == "SortParam":
            allowed = ast.literal_eval(node.args[0])
            to_replace = ast.literal_eval(
                ast.unparse(node.args[2]) and "{"
                + ", ".join(
                    f"{ast.unparse(k)}: 0" for k in node.args[2].keys
                )
                + "}"
            ) if len(node.args) > 2 else {}
            return allowed, set(to_replace)
    raise AssertionError(f"No SortParam call found in {path}")


def resolve(order_by_value, allowed_attrs, to_replace, model):
    """Faithful port of SortParam._resolve for a single value."""
    lstriped = order_by_value.lstrip("-")
    attr_name = lstriped
    column = None
    replacement = to_replace.get(lstriped, lstriped)
    if isinstance(replacement, str):
        lstriped = replacement
    else:
        column = replacement
    if (allowed_attrs and lstriped not in allowed_attrs) and column is None:
        raise HTTP400(
            f"Ordering with '{lstriped}' is disallowed or "
            "the attribute does not exist on the model"
        )
    if column is None:
        column = getattr(model, lstriped)  # <-- raises AttributeError for bad keys
    return attr_name, column


def main():
    failures = 0
    for label, path in REPO_FILES.items():
        allowed, to_replace_keys = parse_sort_param(path)
        print(f"--- {label} ({path}) ---")
        print(f"allowed_attrs={allowed}")
        print(f"to_replace keys={sorted(to_replace_keys)}")
        to_replace = {k: getattr(DagRun, k.split("_", 2)[-1] if k.startswith("last_run_") else k)
                      for k in to_replace_keys}
        cases = ["state", "-state", "start_date", "-start_date",
                 "last_run_state", "-last_run_start_date", "dag_id", "-dag_id"]
        if "last_run_run_after" in to_replace_keys:
            cases.append("last_run_run_after")
        for value in cases:
            try:
                resolve(value, allowed, to_replace, DagModel)
                print(f"  order_by={value!r}: OK")
            except HTTP400 as e:
                print(f"  order_by={value!r}: HTTP 400 ({e})")
            except AttributeError as e:
                failures += 1
                print(f"  order_by={value!r}: AttributeError: {e}")
        print()
    if failures:
        print(f"RESULT: {failures} AttributeError(s) -> BUG PRESENT")
        return 1
    print("RESULT: no AttributeError -> OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
